mapper.select:
SELECT inp.SECID FROM INTERF_PAYHSRCSECINFO inp
LEFT JOIN FIN_PRODUCT fp ON inp.SECID = fp.FINPROD_MARKET_ID
WHERE fp.FINPROD_ID IS NULL
AND inp.SECNAME = #{finprodAbbr,jdbcType=VARCHAR}
AND inp.MARKET  = #{tradeMarket,jdbcType=VARCHAR}

mapper.update:
update FIN_PRODUCT_ADD
set APPEAR_MARKET_ID = '1111'
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
